  app.addHook('preSerialization', async (req, reply, payload) => {
    reply.raw.writeHead(200)
    return payload
  })
}
app.get('/', async () => ({ hello: 'world' }))
app.inject('/').then(
  (r) => console.log('injected', r.statusCode, JSON.stringify(r.payload)),
  (e) => console.log('inject err', e.message)
)

