function handleResolve (newPayload) {
  // `next` can throw synchronously, for example when the response has
  // already been sent and `res.writeHead` fails. We are inside a promise
  // continuation here, so an uncaught throw would become an unhandled
  // rejection the user cannot intercept: route it to `cb`, as it happens
  // when the hooks are not async.
  try {
    next(null, newPayload)
  } catch (error) {
    cb(error, request, reply, payload)
  }
}

function handleReject (err) {
  if (!err) {
    err = new FST_ERR_SEND_UNDEFINED_ERR()
  }

  cb(err, request, reply, payload)
}
